import{_ as a,c as n,o as s,aN as l}from"./chunks/framework.DUf1V_IZ.js";const g=JSON.parse('{"title":"Agent 的运行模式","description":"","frontmatter":{"date":"2026-07-20T10:00:00.000Z","title":"Agent 的运行模式","permalink":"/pages/ag3c91","categories":["AI","Agent"]},"headers":[],"relativePath":"AI/03.Agent/Agent的概念.md","filePath":"AI/03.Agent/Agent的概念.md","lastUpdated":1785469254000}'),e={name:"AI/03.Agent/Agent的概念.md"};function i(r,t,o,d,p,u){return s(),n("div",null,[...t[0]||(t[0]=[l(`<h1 id="agent-的运行模式" tabindex="-1">Agent 的运行模式 <a class="header-anchor" href="#agent-的运行模式" aria-label="Permalink to &quot;Agent 的运行模式&quot;">​</a></h1><h2 id="一、概述" tabindex="-1">一、概述 <a class="header-anchor" href="#一、概述" aria-label="Permalink to &quot;一、概述&quot;">​</a></h2><p>&quot;Agent（智能体）&quot;并非单一形态，而是一条<strong>从&quot;确定式编排&quot;到&quot;自主式决策&quot;的谱系</strong>。同样是&quot;LLM + 工具&quot;，运行模式不同，系统的<strong>可控性、成本、延迟、可预测性</strong>差异巨大。</p><p>理解运行模式的关键，是先看清它们的<strong>共性底座</strong>，再按&quot;谁来决定下一步做什么&quot;来区分。</p><h3 id="基础构建块-增强型-llm-augmented-llm" tabindex="-1">基础构建块：增强型 LLM（Augmented LLM） <a class="header-anchor" href="#基础构建块-增强型-llm-augmented-llm" aria-label="Permalink to &quot;基础构建块：增强型 LLM（Augmented LLM）&quot;">​</a></h3><p>无论哪种模式，底层都是同一个单元：<strong>LLM + 工具调用（Tool）+ 记忆（Memory）+ 检索（RAG）</strong>。</p><ul><li>工具：查天气、读文件、调 API……</li><li>记忆：保存对话/任务状态</li><li>检索：从知识库取资料</li></ul><p>模式的不同，本质是**&quot;控制流由谁掌控&quot;**：</p><ul><li><strong>工作流（Workflow）</strong>：控制流由<strong>开发者预定义的代码</strong>决定（LLM 只在某些节点做判断）。</li><li><strong>智能体（Agent）</strong>：控制流由 <strong>LLM 自身动态决定</strong>（下一步调哪个工具、循环几次，模型说了算）。</li></ul><hr><h2 id="二、多种运行模式拆解" tabindex="-1">二、多种运行模式拆解 <a class="header-anchor" href="#二、多种运行模式拆解" aria-label="Permalink to &quot;二、多种运行模式拆解&quot;">​</a></h2><h3 id="一-工作流模式-workflow-确定性编排" tabindex="-1">（一）工作流模式（Workflow，确定性编排） <a class="header-anchor" href="#一-工作流模式-workflow-确定性编排" aria-label="Permalink to &quot;（一）工作流模式（Workflow，确定性编排）&quot;">​</a></h3><p>LLM 和工具被<strong>写死的代码路径</strong>串起来，流程可预测、易调试，适合步骤明确的任务。</p><h4 id="_1-prompt-链-prompt-chaining" tabindex="-1">1. Prompt 链（Prompt Chaining） <a class="header-anchor" href="#_1-prompt-链-prompt-chaining" aria-label="Permalink to &quot;1. Prompt 链（Prompt Chaining）&quot;">​</a></h4><p>把一个任务拆成<strong>顺序子任务</strong>，上一步输出作为下一步输入。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任务 → [LLM 步骤1] → 中间结果 → [LLM 步骤2] → ... → 最终输出</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>适用：有明确先后依赖的多阶段处理（如 先提取 → 再翻译 → 再总结）。</li><li>优点：简单、可控；可在中间加校验/人工卡点。</li></ul><h4 id="_2-路由-routing" tabindex="-1">2. 路由（Routing） <a class="header-anchor" href="#_2-路由-routing" aria-label="Permalink to &quot;2. 路由（Routing）&quot;">​</a></h4><p>LLM 先<strong>分类/判断</strong>输入，再分流到不同下游处理分支。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入 → [LLM 分类] → 分支A / 分支B / 分支C</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>适用：请求类型多样且处理方式不同（如 售后/技术/账单 分派不同专家提示）。</li><li>优点：针对性强，避免用一套提示处理所有事。</li></ul><h4 id="_3-并行化-parallelization" tabindex="-1">3. 并行化（Parallelization） <a class="header-anchor" href="#_3-并行化-parallelization" aria-label="Permalink to &quot;3. 并行化（Parallelization）&quot;">​</a></h4><p>把任务<strong>同时</strong>发给多个 LLM 调用，再聚合结果。</p><ul><li><strong>分片并行</strong>：同一任务拆成多份并发处理（提速）。</li><li><strong>投票/评审并行</strong>：同一任务多次独立执行，用投票或汇总提高质量。</li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入 → ┬→ [LLM 副本1] ┐</span></span>
<span class="line"><span>       ├→ [LLM 副本2] ┼→ 聚合</span></span>
<span class="line"><span>       └→ [LLM 副本3] ┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ul><li>适用：无依赖的子任务、需要多角度评审（如 安全/质量/合规三路并行检查）。</li></ul><h4 id="_4-编排者-工作者-orchestrator-workers" tabindex="-1">4. 编排者-工作者（Orchestrator-Workers） <a class="header-anchor" href="#_4-编排者-工作者-orchestrator-workers" aria-label="Permalink to &quot;4. 编排者-工作者（Orchestrator-Workers）&quot;">​</a></h4><p>一个<strong>编排者 LLM</strong> 动态拆解任务，把子任务分发给多个<strong>工作者 LLM</strong>，再汇总。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   [编排者 LLM] 拆解任务</span></span>
<span class="line"><span>      ├→ 工作者A（写代码）</span></span>
<span class="line"><span>      ├→ 工作者B（查资料）</span></span>
<span class="line"><span>      └→ 工作者C（测试）</span></span>
<span class="line"><span>         ↓ 汇总</span></span>
<span class="line"><span>      [编排者 合成结果]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><ul><li>适用：无法预先知道子任务划分的复杂任务（如 一个需求拆成多模块开发）。</li></ul><h4 id="_5-评估者-优化者-evaluator-optimizer" tabindex="-1">5. 评估者-优化者（Evaluator-Optimizer） <a class="header-anchor" href="#_5-评估者-优化者-evaluator-optimizer" aria-label="Permalink to &quot;5. 评估者-优化者（Evaluator-Optimizer）&quot;">​</a></h4><p>一个 LLM <strong>生成</strong>，另一个 LLM <strong>评估反馈</strong>，循环迭代直到达标。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[生成者] → 产物 → [评估者 给反馈] → 回到生成者改进 → ... → 通过</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>适用：有清晰评判标准、可迭代优化的任务（如 代码优化、文案润色）。</li></ul><hr><h3 id="二-智能体模式-agent-动态自主" tabindex="-1">（二）智能体模式（Agent，动态自主） <a class="header-anchor" href="#二-智能体模式-agent-动态自主" aria-label="Permalink to &quot;（二）智能体模式（Agent，动态自主）&quot;">​</a></h3><p>LLM <strong>自行决定控制流</strong>：根据观察结果决定下一步调什么工具、是否继续循环，直到任务完成。最典型的是 <strong>ReAct</strong> 范式。</p><h4 id="_6-react-推理-行动" tabindex="-1">6. ReAct（推理 + 行动） <a class="header-anchor" href="#_6-react-推理-行动" aria-label="Permalink to &quot;6. ReAct（推理 + 行动）&quot;">​</a></h4><p>模型交替进行<strong>思考（Thought）→ 行动（Action/调工具）→ 观察（Observation）</strong>，循环直至给出答案。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Thought: 我需要先查天气</span></span>
<span class="line"><span>Action: call WeatherTool(&quot;北京&quot;)</span></span>
<span class="line"><span>Observation: 晴, 25℃</span></span>
<span class="line"><span>Thought: 信息够了，可以回答</span></span>
<span class="line"><span>Answer: 北京今天晴...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><ul><li>适用：需多步工具调用、路径不固定的开放式任务。</li><li>优点：灵活、能处理意外；缺点：可能循环过多、成本/延迟不可控。</li></ul><h4 id="_7-plan-and-execute-规划后执行" tabindex="-1">7. Plan-and-Execute（规划后执行） <a class="header-anchor" href="#_7-plan-and-execute-规划后执行" aria-label="Permalink to &quot;7. Plan-and-Execute（规划后执行）&quot;">​</a></h4><p>先由 LLM <strong>一次性规划</strong>出完整步骤，再逐步执行（执行中可微调）。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>规划者 LLM: [步骤1][步骤2][步骤3]  →  执行者依次完成（可调用工具）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>与 ReAct 区别：ReAct 是&quot;走一步看一步&quot;，Plan-and-Execute 是&quot;先画全局地图再走&quot;。</li><li>适用：步骤可预估、希望减少无效探索的任务；常配合子 Agent 执行。</li></ul><h4 id="_8-reflection-反思-自省" tabindex="-1">8. Reflection（反思 / 自省） <a class="header-anchor" href="#_8-reflection-反思-自省" aria-label="Permalink to &quot;8. Reflection（反思 / 自省）&quot;">​</a></h4><p>生成后让模型<strong>自我批评/复盘</strong>，基于反思改进产物，可多轮。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>生成初稿 → 反思(哪里不对) → 修订 → 再反思 → 终稿</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>可视为 Evaluator-Optimizer 的&quot;自我版&quot;（同一个模型既生成又评估）。</li><li>适用：写作、方案设计等需要打磨质量的场景。</li></ul><h4 id="_9-多智能体协作-multi-agent" tabindex="-1">9. 多智能体协作（Multi-Agent） <a class="header-anchor" href="#_9-多智能体协作-multi-agent" aria-label="Permalink to &quot;9. 多智能体协作（Multi-Agent）&quot;">​</a></h4><p>多个<strong>角色不同</strong>的 Agent 互相通信、分工或辩论，共同完成目标。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[产品经理 Agent] ⇄ [工程师 Agent] ⇄ [测试 Agent]</span></span>
<span class="line"><span>       通过共享消息总线协作</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ul><li>形态：分工协作、对抗辩论（如 红队/蓝队）、评审委员会。</li><li>适用：复杂项目、需要多角度碰撞（如 自动软件开发团队）。</li></ul><h4 id="_10-人机协同-human-in-the-loop-hitl" tabindex="-1">10. 人机协同（Human-in-the-Loop, HITL） <a class="header-anchor" href="#_10-人机协同-human-in-the-loop-hitl" aria-label="Permalink to &quot;10. 人机协同（Human-in-the-Loop, HITL）&quot;">​</a></h4><p>在关键节点<strong>暂停等待人类确认/输入</strong>，再继续。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent 执行 → 遇到高风险操作 → 请求人工批准 → 人工确认 → 继续</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>不是独立模式，而是叠加在上述任意模式上的<strong>安全护栏</strong>。</li><li>适用：涉及资金、删除、外发等不可逆/高风险动作。</li></ul><hr><h2 id="三、运行模式对比表" tabindex="-1">三、运行模式对比表 <a class="header-anchor" href="#三、运行模式对比表" aria-label="Permalink to &quot;三、运行模式对比表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>控制流</th><th>自主性</th><th>可预测性</th><th>成本/延迟</th><th>适用场景</th></tr></thead><tbody><tr><td>Prompt 链</td><td>代码固定顺序</td><td>低</td><td>高</td><td>低</td><td>多阶段线性任务</td></tr><tr><td>路由</td><td>代码分支</td><td>低</td><td>高</td><td>低</td><td>请求分类型处理</td></tr><tr><td>并行化</td><td>代码并发</td><td>低</td><td>高</td><td>中（并发）</td><td>无依赖子任务/多评审</td></tr><tr><td>编排者-工作者</td><td>编排者动态拆</td><td>中</td><td>中</td><td>中高</td><td>复杂不可预拆分任务</td></tr><tr><td>评估者-优化者</td><td>代码循环</td><td>中</td><td>中</td><td>中高</td><td>可迭代优化任务</td></tr><tr><td>ReAct</td><td><strong>LLM 动态</strong></td><td>高</td><td>低</td><td>高（易失控）</td><td>开放式多步任务</td></tr><tr><td>Plan-and-Execute</td><td>LLM 规划+执行</td><td>高</td><td>中</td><td>中</td><td>步骤可预估的复杂任务</td></tr><tr><td>Reflection</td><td>LLM 自省循环</td><td>高</td><td>中</td><td>中高</td><td>需打磨质量的生成</td></tr><tr><td>多智能体</td><td>多 LLM 协商</td><td>高</td><td>低</td><td>高</td><td>大型协作项目</td></tr><tr><td>人机协同(HITL)</td><td>叠加式</td><td>可控</td><td>高</td><td>取决于人</td><td>高风险操作</td></tr></tbody></table><blockquote><p>维度说明：<strong>自主性</strong>越高越灵活但越难预测；<strong>可预测性</strong>越高越易调试与保障；二者通常此消彼长。</p></blockquote><hr><h2 id="四、选型建议" tabindex="-1">四、选型建议 <a class="header-anchor" href="#四、选型建议" aria-label="Permalink to &quot;四、选型建议&quot;">​</a></h2><ol><li><strong>能用工作流就别用 Agent</strong>：Anthropic 的经典建议——多数场景用<strong>确定性工作流</strong>即可，简单、便宜、可控；只有当任务<strong>路径无法预先写死</strong>时才上自主 Agent。</li><li><strong>从简单到复杂演进</strong>： <ul><li>步骤固定 → Prompt 链 / 路由</li><li>需多视角 → 并行化</li><li>子任务未知 → 编排者-工作者</li><li>需打磨 → 评估者-优化者 / Reflection</li><li>真正开放多步 → ReAct / 多智能体</li></ul></li><li><strong>永远保留护栏</strong>：无论哪种模式，涉及高风险动作都叠加 <strong>Human-in-the-Loop</strong> 与<strong>工具权限最小化</strong>。</li><li><strong>可观测性优先</strong>：自主模式必须记录每步的 Thought/Action/Observation，否则出了问题无法排查。</li></ol><blockquote><p>记忆口诀：<strong>工作流是&quot;代码定路线&quot;，Agent 是&quot;模型自己走&quot;；越自主越灵活也越难控，能确定性编排就别上自主。</strong></p></blockquote><hr><h2 id="五、agent-skill-智能体技能" tabindex="-1">五、Agent Skill（智能体技能） <a class="header-anchor" href="#五、agent-skill-智能体技能" aria-label="Permalink to &quot;五、Agent Skill（智能体技能）&quot;">​</a></h2><h3 id="_1-什么是-agent-skill" tabindex="-1">1. 什么是 Agent Skill <a class="header-anchor" href="#_1-什么是-agent-skill" aria-label="Permalink to &quot;1. 什么是 Agent Skill&quot;">​</a></h3><p><strong>Agent Skill（智能体技能）</strong> 是为 Agent <strong>预置的、封装好的专用能力包</strong>：把某个领域的<strong>知识、标准操作流程（SOP）、可调用的工具/脚本</strong>打包在一起，让 Agent 在该领域像&quot;受过培训的专家&quot;一样工作。</p><ul><li>类比：<strong>Agent 是通才员工，Skill 是上岗培训手册 + 专用工具箱</strong>。</li><li>与&quot;运行模式&quot;的关系：运行模式解决&quot;<strong>怎么干活</strong>（控制流）&quot;，Skill 解决&quot;<strong>按什么套路干</strong>（领域专长）&quot;。二者正交——任何运行模式（ReAct、Plan-and-Execute…）都能加载任意 Skill。</li></ul><h3 id="_2-为什么需要-skill" tabindex="-1">2. 为什么需要 Skill <a class="header-anchor" href="#_2-为什么需要-skill" aria-label="Permalink to &quot;2. 为什么需要 Skill&quot;">​</a></h3><table tabindex="0"><thead><tr><th>痛点</th><th>Skill 的解法</th></tr></thead><tbody><tr><td>每次都要在 Prompt 里重复写领域规范，Prompt 越来越长</td><td>规范固化进 Skill，用时才注入，<strong>省 Token</strong></td></tr><tr><td>不同任务质量参差不齐，依赖临场发挥</td><td>Skill 提供<strong>标准化 SOP</strong>，输出更稳更可复现</td></tr><tr><td>专家经验难以复用</td><td>一次封装，<strong>多人/多 Agent 共享</strong></td></tr><tr><td>复杂任务易漏步骤</td><td>Skill 显式列出<strong>检查清单/步骤</strong></td></tr></tbody></table><h3 id="_3-skill-通常包含什么" tabindex="-1">3. Skill 通常包含什么 <a class="header-anchor" href="#_3-skill-通常包含什么" aria-label="Permalink to &quot;3. Skill 通常包含什么&quot;">​</a></h3><ul><li><strong>领域知识</strong>：术语、约定、最佳实践（如某框架的编码规范）。</li><li><strong>SOP / 步骤清单</strong>：标准操作流程（先做什么、后做什么、注意什么）。</li><li><strong>工具与脚本</strong>：可执行的命令、脚本、或绑定的 MCP 工具。</li><li><strong>触发条件</strong>：什么意图下该激活此 Skill（关键词、任务类型）。</li><li><strong>输出模板</strong>：期望的产物格式（如报告结构、提交信息格式）。</li></ul><h3 id="_4-skill-与-tool-mcp-的区别" tabindex="-1">4. Skill 与 Tool / MCP 的区别 <a class="header-anchor" href="#_4-skill-与-tool-mcp-的区别" aria-label="Permalink to &quot;4. Skill 与 Tool / MCP 的区别&quot;">​</a></h3><table tabindex="0"><thead><tr><th>概念</th><th>粒度</th><th>角色</th></tr></thead><tbody><tr><td>Tool（工具）</td><td>原子能力</td><td>&quot;手&quot;——查天气、读文件等单个动作</td></tr><tr><td>MCP</td><td>协议</td><td>统一连接 Tool 的&quot;接口标准&quot;（USB-C）</td></tr><tr><td><strong>Agent Skill</strong></td><td><strong>编排好的工作流</strong></td><td>&quot;专家套路&quot;——把多个 Tool + 知识 + SOP 组合成一套打法</td></tr></tbody></table><blockquote><p>一句话：<strong>Tool 是积木，Skill 是用积木搭好的&quot;成品模型&quot;；MCP 是积木的通用接口。</strong></p></blockquote><h3 id="_5-触发与加载机制" tabindex="-1">5. 触发与加载机制 <a class="header-anchor" href="#_5-触发与加载机制" aria-label="Permalink to &quot;5. 触发与加载机制&quot;">​</a></h3><ul><li><strong>自动触发</strong>：Agent 识别用户意图匹配某 Skill 时，自动将其指令<strong>注入 Context</strong>（进入系统/用户提示），指导后续行为。</li><li><strong>显式调用</strong>：用户或编排者直接指定&quot;使用 XX 技能&quot;。</li><li><strong>按需卸载</strong>：任务完成后 Skill 指令退出上下文，避免长期占用窗口、干扰其他任务。</li><li>关键点：Skill 本质是<strong>动态注入的上下文 + 可调用资源</strong>，不改变模型本身，也不改变运行模式。</li></ul><h3 id="_6-skill-如何与运行模式结合" tabindex="-1">6. Skill 如何与运行模式结合 <a class="header-anchor" href="#_6-skill-如何与运行模式结合" aria-label="Permalink to &quot;6. Skill 如何与运行模式结合&quot;">​</a></h3><p>以 <strong>ReAct</strong> 为例，加载&quot;代码审查 Skill&quot;后循环变为：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Thought: 用户要我审这段代码，先加载代码审查 Skill 的清单</span></span>
<span class="line"><span>Action: 按 SOP 步骤1——检查空值/异常处理</span></span>
<span class="line"><span>Observation: 发现第 12 行未处理 null</span></span>
<span class="line"><span>Thought: 继续步骤2——检查并发安全</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>Answer: 附修复建议的审查报告（按 Skill 模板输出）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>即：运行模式提供&quot;循环引擎&quot;，Skill 提供&quot;领域驾驶手册&quot;。</p><h3 id="_7-常见-skill-示例" tabindex="-1">7. 常见 Skill 示例 <a class="header-anchor" href="#_7-常见-skill-示例" aria-label="Permalink to &quot;7. 常见 Skill 示例&quot;">​</a></h3><ul><li><strong>代码审查 Skill</strong>：按清单检查空指针、并发、安全、命名，输出结构化报告。</li><li><strong>架构图绘制 Skill</strong>：调用 drawio/Mermaid 工具，按规范生成图示。</li><li><strong>周报生成 Skill</strong>：聚合 Git 提交/任务系统数据，套模板生成周报。</li><li><strong>SQL 优化 Skill</strong>：结合执行计划分析，给出索引/改写建议。</li></ul><h3 id="_8-最佳实践" tabindex="-1">8. 最佳实践 <a class="header-anchor" href="#_8-最佳实践" aria-label="Permalink to &quot;8. 最佳实践&quot;">​</a></h3><ol><li><strong>单一职责</strong>：一个 Skill 解决一类明确任务，避免大而全。</li><li><strong>SOP 可验证</strong>：步骤尽量可机器检查，而非仅靠模型&quot;自觉&quot;。</li><li><strong>与 Tool/MCP 解耦</strong>：Skill 调用底层 Tool，但不把 Tool 实现细节写死。</li><li><strong>控制注入体积</strong>：只注入当前任务需要的 Skill，保护 Context Window。</li><li><strong>可版本化</strong>：Skill 当作代码管理，便于迭代与回滚。</li></ol><blockquote><p>记忆口诀：<strong>Tool 是手，MCP 是接口，Skill 是专家套路；运行模式管&quot;怎么走&quot;，Skill 管&quot;按啥走&quot;。</strong></p></blockquote>`,88)])])}const c=a(e,[["render",i]]);export{g as __pageData,c as default};
